  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'پیشرفت بازپخش، وضعیت تماشای بعد، لایک‌ها، نظرات، اشتراک‌ها، اعلان‌ها، و تجزیه و تحلیل‌های سرپرست در پایگاه داده ذخیره می‌شوند که به ویژگی‌های پلتفرم تأیید شده مرتبط شوند.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'پخش، نظرات، لایک‌ها، تماشا کردن در فرصتی دیگر، اشتراک‌ها، اعلان‌ها، پیام‌ها، فهرست‌های پخش و تنظیمات زبان از طریق منوی پیمایش و حساب اصلی در دسترس هستند.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub یک پلت فرم ویدیویی برای آپلود، تماشا، زمان‌بندی، مدیریت و تعدیل محتوای سازنده از یک حساب است.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub پلت فرم ویدیویی است که بر روی این استقرار اجرا می شود و برای سازندگان، بینندگان، جوامع و اپراتورهای پلت فرم ساخته شده است.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub کانال‌های سازنده، آپلود ویدیو، انتشار برنامه‌ریزی‌شده، اشتراک‌ها، نظرات، فهرست‌های پخش، تماشای بعد، صفحات محتوای زنده و ابزارهای مدیریتی را از یک پلتفرم فراهم می‌کند.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub از کوکی‌های ضروری و ذخیره‌سازی مرورگر برای جلسات ورود به سیستم، احراز هویت API، رفتار CSRF/امنیتی، انتخاب زبان، انتخاب تم، وضعیت منوی حساب و سایر ویژگی‌های مورد نیاز برای کارکرد برنامه استفاده می‌کند.',
