  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'رسیدگی به بازپرداخت با سوابق صورت‌حساب واقعی و بررسی سرپرست مرتبط است. اگر صورت‌حساب برای این استقرار پیکربندی نشده باشد، هیچ هزینه پلتفرمی برای بازپرداخت وجود ندارد.',
  'Refund issued' => 'بازپرداخت صادر شد',
