  'Select a reason' => 'دلیلی را انتخاب کنید',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'یک یا چند فایل ویدیویی را انتخاب کنید، جزئیات مورد نیاز را وارد کنید، دسته و زبان را انتخاب کنید، یک تصویر کوچک اضافه کنید، قابلیت مشاهده را انتخاب کنید و منتشر کنید. فایل های بزرگ قبل از شروع پردازش سرور به صورت تکه ای آپلود می شوند.',
  'Send a message and it will be saved for admins.' => 'یک پیام ارسال کنید و برای ادمین ها ذخیره می شود.',
  'Send billing details to admin support for review.' => 'جزئیات صورتحساب را برای بررسی به پشتیبانی سرپرست ارسال کنید.',
  'Send message' => 'ارسال پیام',
