  'Settings and login' => 'تنظیمات و ورود به سیستم',
  'Short summary' => 'خلاصه کوتاه',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'وارد شوید و از تنظیمات برای حساب، نمایه، رمز عبور، اعلان، حریم خصوصی و تنظیمات برگزیده سازنده استفاده کنید. مسائل مربوط به آپلود محتوا و محتوا باید شامل عنوان ویدیو، کانال، مرورگر و هرگونه خطای پردازشی نشان داده شده در صفحه آپلود باشد.',
  'Sign in for account support' => 'برای پشتیبانی حساب وارد شوید',
  'Signed in' => 'وارد شده است',
  'Start uploading' => 'شروع به آپلود کنید',
  'Still can’t find an answer?' => 'هنوز نمی توانید پاسخی پیدا کنید؟',
  'Stored for admins' => 'ذخیره شده برای مدیران',
  'Stores language, theme, and interface preferences.' => 'تنظیمات زبان، تم و رابط کاربری را ذخیره می کند.',
  'Studio, playlists, analytics, channels.' => 'استودیو، لیست پخش، تجزیه و تحلیل، کانال ها.',
  'Submit a billing or refund message to admin support.' => 'یک پیام صورتحساب یا بازپرداخت به پشتیبانی سرپرست ارسال کنید.',
  'Submit refund request' => 'درخواست بازپرداخت را ارسال کنید',
  'Submit request' => 'درخواست ارسال کنید',
  'Subscription cancellation' => 'لغو اشتراک',
  'Support dashboard' => 'داشبورد پشتیبانی',
  'System status' => 'وضعیت سیستم',
  'Table' => 'جدول',
  'Taxonomies' => 'طبقه بندی ها',
  'Technical issue' => 'مسئله فنی',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'نکات فنی برای ادغام با API فعلی PlayHub و گردش کار آپلود.',
  'Tell us more about your question or request...' => 'درباره سوال یا درخواست خود بیشتر به ما بگویید...',
  'Terms of Use' => 'شرایط استفاده',
  'The configured' => 'پیکربندی شده است',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'صفحه توسعه‌دهنده به باطن لاراول متصل است: موجودی مسیر، تعداد پایگاه داده، محدودیت‌های آپلود، و ابرداده پلتفرم از /api/developers بارگیری می‌شوند.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'صفحه اصلی تنظیمات برگزیده مانند زبان انتخاب شده، موضوع، صف پخش، پیشرفت تماشا و وضعیت رابط را ذخیره می کند تا تجربه در طول پیمایش و بارگیری مجدد صفحه ثابت بماند.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'کار پردازش، تفسیرها را رمزگذاری می‌کند، در صورت نیاز، تصاویر کوچک ایجاد می‌کند، زیرنویس‌ها را ذخیره می‌کند، و ویدیوها را پس از تکمیل پردازش، آماده علامت‌گذاری می‌کند. ویدیوهای برنامه ریزی شده آینده تا زمانی که زمانبندی آنها را منتشر نکند خصوصی می مانند.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'سیستم آپلود مبتنی بر پایگاه داده است، از دسته‌ها و زبان‌های API پشتیبانی می‌کند، ویدیوهای آپلود شده را پردازش می‌کند، تصاویر کوچک و زیرنویس‌ها را ذخیره می‌کند و محتوای برنامه‌ریزی‌شده را تا زمان انتشار خصوصی نگه می‌دارد.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'این صفحه توضیح می‌دهد که چگونه PlayHub از کوکی‌ها و فضای ذخیره‌سازی مرورگر برای جلسات، امنیت، تنظیمات برگزیده، پخش و ویژگی‌های احراز هویت استفاده می‌کند.',
  'Ticket source' => 'منبع بلیط',
