  'Upload options' => 'گزینه های آپلود',
  'Upload or processing' => 'آپلود یا پردازش',
  'Upload page' => 'صفحه آپلود',
  'Upload pipeline' => 'خط لوله بارگذاری کنید',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'آپلود، تماشا، اشتراک، تعدیل، و ساخت با داده های PlayHub زنده.',
  'Uploaded videos' => 'ویدیوهای آپلود شده',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'ویدیوهای آپلود شده به صورت نمایش های قابل پخش کدگذاری می شوند. زمان پردازش به اندازه فایل، مدت زمان، بارگذاری سرور و وضعیت صف بستگی دارد. صفحه آپلود و Creator Studio وضعیت پردازش واقعی را از ضبط ویدیو نشان می دهد.',
  'Uploads, scheduling, and processing are available.' => 'آپلود، زمان‌بندی و پردازش در دسترس است.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'از /api/videos، نقاط پایانی کانال و مسیرهای احراز هویت شده برای گردش کار سازنده استفاده کنید.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'از اقدامات گزارش داخلی برای ویدیوها و نظرات استفاده کنید تا مدیران مرجع محتوای دقیق را دریافت کنند. صفحات داشبورد مدیریت از داده های پایگاه داده زنده برای کاربران، محتوا، گزارش ها، کسب درآمد، تجزیه و تحلیل، پشتیبانی، نقش ها و تنظیمات سیستم استفاده می کنند.',
  'Use Contact Us' => 'استفاده از تماس با ما',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'از JSON برای درخواست های API معمولی و از FormData برای آپلود فایل استفاده کنید. اعتبارسنجی را دور نزنید: دسته‌ها و زبان‌ها شناسه‌های پایگاه داده هستند، قابلیت مشاهده محدود به عمومی، فهرست‌نشده یا خصوصی است و زیرنویس‌ها فایل‌های SRT، VTT یا TXT را می‌پذیرند.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'از تنظیمات برای به‌روزرسانی نمایه، امنیت، رمز عبور، تحویل دو مرحله‌ای، دستگاه‌ها، تنظیمات برگزیده و گزینه‌های اعلان استفاده کنید. اگر نمی توانید به حساب خود دسترسی پیدا کنید، از جریان ورود استفاده کنید و ایمیل حساب را در اختیار مدیر سایت قرار دهید.',
  'Use the contact form' => 'از فرم تماس استفاده کنید',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'از اقدامات گزارش روی ویدیوها، نظرات و پست‌های انجمن استفاده کنید تا مدیران مرجع دقیق محتوا را دریافت کنند.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'زمانی که ممکن است محتوا قوانین پلتفرم را نقض کند، از اقدامات گزارش در ویدیوها، نظرات و پست‌های انجمن استفاده کنید. این گزارش ها به رکورد محتوای واقعی گره خورده اند و بهتر از یک پیام عمومی هستند زیرا مدیران می توانند مورد دقیق را بررسی کنند.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'از کانال PlayHub مناسب برای راهنمایی حساب، گزارشات محتوا، مشکلات فنی و درخواست‌های سرپرست استفاده کنید.',
  'Video categories' => 'دسته بندی های ویدئویی',
  'Video for everyone. Built for creators and viewers.' => 'ویدیو برای همه ساخته شده از داده های پلت فرم واقعی.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'مشکلات آپلود، زمان‌بندی، ریز عکس‌ها و پردازش ویدیو.',
  'Videos, thumbnails, captions, processing.' => 'فیلم‌ها، تصاویر کوچک، زیرنویس‌ها، پردازش.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'بینندگان می‌توانند دسته‌ها را مرور کنند، ویدیوها را جستجو کنند، محتوا را تماشا کنند، در کانال‌ها مشترک شوند، ویدیوها را ذخیره کنند تا بعداً تماشا کنند، نظر بدهند، اعلان‌ها را دریافت کنند و اولویت‌های زبان و دسترسی را مدیریت کنند.',
  'Viewing and community help' => 'مشاهده و کمک انجمن',
  'Waiting for backend endpoint inventory.' => 'در انتظار موجودی نقطه پایانی باطن.',
  'We’re here to help.' => 'ما اینجا هستیم تا کمک کنیم.',
  'What is PlayHub?' => 'PlayHub چیست؟',
  'What PlayHub does' => 'کاری که PlayHub انجام می دهد',
  'Where do contact messages go?' => 'پیام های تماس کجا می روند؟',
  'Why is my video still processing?' => 'چرا ویدیوی من هنوز در حال پردازش است؟',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'بله. از فیلد تاریخ و زمان برنامه بومی در صفحه آپلود استفاده کنید. پشتیبان scheduled_at را ذخیره می‌کند، ویدیو را پردازش می‌کند، آن را تا زمانی که تاریخ در آینده است، خصوصی نگه می‌دارد، و زمانی که زمان‌بندی لاراول بعد از زمان برنامه‌ریزی‌شده اجرا شود، آن را منتشر می‌کند.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'بله. از فیلد برنامه بومی در آپلود استفاده کنید. باطن scheduled_at را ذخیره می کند و پس از پردازش، پس از رسیدن به زمان برنامه، ویدیو را منتشر می کند.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'شما به عنوان مهمان در حال مرور هستید. برای دسترسی به ابزارهای خاص حساب وارد شوید.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'شما مسئول اعتبار حساب، فعالیت نمایه، محتوای آپلود شده، نظرات، پیام‌ها و هر اقدام سازنده یا سرپرستی هستید که از حساب شما انجام می‌شود. از رمزهای عبور قوی استفاده کنید و روش های تحویل دو مرحله ای را به روز نگه دارید.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'می‌توانید کوکی‌های مرورگر و فضای ذخیره‌سازی محلی را در تنظیمات مرورگر خود پاک کنید. پاک کردن فضای ذخیره‌سازی ضروری ممکن است شما را از سیستم خارج کنید، تنظیمات برگزیده زبان/موضوع را بازنشانی کند، وضعیت پخش محلی را حذف کند و از شما بخواهد دوباره وارد سیستم شوید.',
  'You receive a response by email.' => 'شما از طریق ایمیل پاسخ دریافت می کنید.',
  'You’re in control' => 'شما در کنترل هستید',
  'Your choices' => 'انتخاب های شما',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'پیام شما مستقیماً در باطن وب سایت ذخیره می شود و در داشبورد مدیریت در قسمت پشتیبانی ظاهر می شود.',
  'Your support' => 'حمایت شما',
  'Watch video' => 'ویدیو را تماشا کنید',
  'Copy link' => 'لینک را کپی کنید',
  'View creator' => 'مشاهده سازنده',
  'Remove from playlist' => 'حذف از لیست پخش',
  'Removing videos from playlists is not available here yet.' => 'حذف ویدیوها از لیست‌های پخش هنوز در اینجا در دسترس نیست.',
  'Create New Playlist' => 'ایجاد لیست پخش جدید',
  'Organize your videos into a playlist' => 'ویدیوهای خود را در یک لیست پخش سازماندهی کنید',
  'Playlist Name' => 'نام لیست پخش',
  'e.g. Travel Vlogs 2025' => 'به عنوان مثال ولوگ های مسافرتی 2025',
  '(optional)' => '(اختیاری)',
  'What’s this playlist about?' => 'این لیست پخش درباره چیست؟',
  'Select Color' => 'رنگ را انتخاب کنید',
  'This color will represent your playlist' => 'این رنگ نمایانگر لیست پخش شما خواهد بود',
  'Anyone can view this playlist' => 'همه می توانند این لیست پخش را مشاهده کنند',
  'Only you can view this playlist' => 'فقط شما می توانید این لیست پخش را مشاهده کنید',
  'Anyone with the link can view' => 'هر کسی که پیوند را داشته باشد می تواند مشاهده کند',
  'Add to Playlist' => 'به لیست پخش اضافه کنید',
  'Add videos to this playlist now' => 'اکنون ویدیوها را به این لیست پخش اضافه کنید',
